import copy

def rotate_90(grid):
    """Rotate 90 degrees clockwise"""
    return [list(row)[::-1] for row in zip(*grid)]

def rotate_180(grid):
    return rotate_90(rotate_90(grid))

def rotate_270(grid):
    return rotate_90(rotate_270(grid))

